[meta]
name = Herran's Spire
ambient = 0.86 0.8 0.74
fog = 0.66 0.67 0.76
fog_range = 22 120
model_range = 64
indoor_range = 22
sky = storm
torch = 6 0.95 0.8 0.6
start = 12 37 -90
default = _
entity_floor = auto
roofs = true
edge_top = -40
edge_tex = herran_ashlar

// Herran's Spire, the tallest of his towers, at the head of the castle: the base hall behind the
// door the Spire Key opens, the stair up to the drake hatchery where his vats still bubble, the stair
// on up to his study and the shrine there, and beyond his door, out over the clouds on the tower's
// flank, the observatory under its broken dome, where Herran, the Many-Handed waits by his telescope
// with the Auric Sigil, the fifth seal, the sun's.

[legend]
_ = floor tex=cloud_sea h=-40 side=herran_ashlar chasm fall=cloud void
& = wall tex=herran_brick top=40 cap=herran_slate
v = wall tex=herran_ashlar top=12.1 cap=herran_ashlar
// The base hall, where the castle's door lets you in.
a = floor tex=encaustic_tile h=0 ceil=7 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.2
// The stair up to the hatchery, half a metre a tile, each step under its own vault.
b = floor tex=encaustic_tile h=0.5 ceil=5.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
c = floor tex=encaustic_tile h=1 ceil=6 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
d = floor tex=encaustic_tile h=1.5 ceil=6.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
e = floor tex=encaustic_tile h=2 ceil=7 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
f = floor tex=encaustic_tile h=2.5 ceil=7.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
g = floor tex=encaustic_tile h=3 ceil=8 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
h = floor tex=encaustic_tile h=3.5 ceil=8.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
i = floor tex=encaustic_tile h=4 ceil=9 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
j = floor tex=encaustic_tile h=4.5 ceil=9.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
k = floor tex=encaustic_tile h=5 ceil=10 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
l = floor tex=encaustic_tile h=5.5 ceil=10.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
m = floor tex=encaustic_tile h=6 ceil=11 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
// The drake hatchery, 6 m up.
H = floor tex=lab_tile h=6 ceil=11 ceil_tex=lab_tile side=lab_tile roof=40 dark=0.35
// The stair on up to Herran's study.
n = floor tex=encaustic_tile h=6.5 ceil=11 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
o = floor tex=encaustic_tile h=7 ceil=11.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
p = floor tex=encaustic_tile h=7.5 ceil=12 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
q = floor tex=encaustic_tile h=8 ceil=12.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
r = floor tex=encaustic_tile h=8.5 ceil=13 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
s = floor tex=encaustic_tile h=9 ceil=13.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
t = floor tex=encaustic_tile h=9.5 ceil=14 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
x = floor tex=encaustic_tile h=10 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
y = floor tex=encaustic_tile h=10.5 ceil=15 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
z = floor tex=encaustic_tile h=11 ceil=15.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.3
// Herran's study, 11 m up, and the passage out to his observatory.
S = floor tex=encaustic_tile h=11 ceil=15.5 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.2
P = floor tex=encaustic_tile h=11 ceil=15 ceil_tex=herran_ashlar side=herran_brick roof=40 dark=0.2
// The observatory's floor, open to the sky, ringed by its parapet over the clouds.
O = floor tex=herran_ashlar h=11 side=herran_ashlar

